questions.frontEndCss:
* {
    box-sizing: border-box;
}

body {
    margin: 0;
    padding: 24px 16px;
    font-family: 'Trebuchet MS', 'Segoe UI', Arial, sans-serif;
    font-size: 16px;
    line-height: 1.45;
    color: #111111;
    background-color: #FFF7ED;
}

.card {
    max-width: 480px;
    margin: 0 auto;
    background-color: #FFFFFF;
    border: 3px solid #111111;
    border-radius: 16px;
    box-shadow: 8px 8px 0 #111111;
}

.card-head {
    padding: 18px 20px 0;
}

.badge {
    display: inline-block;
    padding: 2px 10px;
    font-size: 12px;
    font-weight: 700;
    background-color: #FDE68A;
    border: 2px solid #111111;
    border-radius: 999px;
}

.card h1 {
    margin: 8px 0 0;
    font-size: 26px;
    font-weight: 900;
    letter-spacing: -0.5px;
}

.tagline {
    margin: 4px 0 0;
    font-size: 14px;
    color: #4B5563;
}

.card-body {
    padding: 18px 20px 20px;
}

.field {
    margin-bottom: 14px;
}

.field-label {
    display: block;
    margin-bottom: 6px;
    font-size: 14px;
    font-weight: 700;
}

.row {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    align-items: flex-end;
}

.row .field {
    flex: 1 1 120px;
    margin-bottom: 0;
}

.input {
    width: 100%;
    padding: 12px 14px;
    font-family: 'Trebuchet MS', 'Segoe UI', Arial, sans-serif;
    font-size: 16px;
    color: #111111;
    background-color: #FFFFFF;
    border: 3px solid #111111;
    border-radius: 10px;
}

.input:focus {
    outline: none;
    background-color: #FEF3C7;
    box-shadow: 4px 4px 0 #111111;
}

.btn {
    display: inline-block;
    padding: 12px 18px;
    font-family: 'Trebuchet MS', 'Segoe UI', Arial, sans-serif;
    font-size: 15px;
    font-weight: 800;
    color: #FFFFFF;
    background-color: #111111;
    border: 3px solid #111111;
    border-radius: 10px;
    box-shadow: 4px 4px 0 #A78BFA;
    cursor: pointer;
}

.btn:hover {
    transform: translate(-2px, -2px);
    box-shadow: 6px 6px 0 #A78BFA;
}

.btn:active {
    transform: translate(2px, 2px);
    box-shadow: 0 0 0 #A78BFA;
}

.btn:focus-visible {
    outline: 3px dashed #7C3AED;
    outline-offset: 3px;
}

.btn-alt {
    color: #111111;
    background-color: #A7F3D0;
    box-shadow: 4px 4px 0 #111111;
}

.btn-alt:hover {
    box-shadow: 6px 6px 0 #111111;
}

.actions {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 16px;
}

.result {
    margin-top: 16px;
    padding: 14px 16px;
    min-height: 52px;
    font-weight: 700;
    font-size: 18px;
    background-color: #ECFCCB;
    border: 3px dashed #111111;
    border-radius: 12px;
}

.note {
    margin: 10px 0 0;
    font-size: 13px;
    color: #4B5563;
}

.list {
    list-style: none;
    margin: 0;
    padding: 0;
}

.list li {
    padding: 10px 12px;
    border-bottom: 2px solid #111111;
}

.check {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 16px;
    font-weight: 700;
}

.check input {
    width: 20px;
    height: 20px;
}

/* ===== Weekday Lookup ===== */
.day-label {
    display: block;
    margin-bottom: 6px;
    font-size: 14px;
    font-weight: 700;
}

.day-out {
    /* TODO: Set background-color to #A7F3D0 */
}

questions.frontEndJs:
function initApp() {
    var dayInput = document.getElementById('dayInput');
    var lookupBtn = document.getElementById('lookupBtn');
    var dayOut = document.getElementById('dayOut');
    var days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

    lookupBtn.addEventListener('click', function () {
        var n = parseFloat(dayInput.value);
        // TODO: If n is NaN, below 1, above 7 or not whole show "Enter 1 to 7";
        // otherwise show "Day " + n + " is " + days[n - 1].

    });
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initApp);
} else {
    initApp();
}

